class Solution:
    def wonderfulSubstrings(self, word: str) -> int:
        counts = [0] * 1024
        counts[0] = 1
        mask = 0
        res = 0
        for ch in word:
            mask ^= 1 << (ord(ch) - ord('a'))
            res += counts[mask]
            for b in range(10):
                res += counts[mask ^ (1 << b)]
            counts[mask] += 1
        return res

class Solution {
public:
    long long wonderfulSubstrings(string word) {
        vector<int> counts(1024, 0);
        counts[0] = 1;
        int mask = 0;
        long long res = 0;
        for (char ch : word) {
            mask ^= (1 << (ch - 'a'));
            res += counts[mask];
            for (int b = 0; b < 10; b++) {
                res += counts[mask ^ (1 << b)];
            }
            counts[mask]++;
        }
        return res;
    }
};

class Solution {
    public long wonderfulSubstrings(String word) {
        int[] counts = new int[1024];
        counts[0] = 1;
        int mask = 0;
        long res = 0;
        for (char ch : word.toCharArray()) {
            mask ^= (1 << (ch - 'a'));
            res += counts[mask];
            for (int b = 0; b < 10; b++) {
                res += counts[mask ^ (1 << b)];
            }
            counts[mask]++;
        }
        return res;
    }
}

var wonderfulSubstrings = function(word) {
  const counts = new Int32Array(1024);
  counts[0] = 1;
  let mask = 0;
  let res = 0;
  for (let i = 0; i < word.length; i++) {
    mask ^= 1 << (word.charCodeAt(i) - 97);
    res += counts[mask];
    for (let b = 0; b < 10; b++) {
      res += counts[mask ^ (1 << b)];
    }
    counts[mask]++;
  }
  return res;
};
